// Section.js
import { useContext } from 'react';
import { LevelContext } from './LevelContext.js';

export function Section({ children }) {
  const level = useContext(LevelContext); // consume
  return (
    <section>
      <LevelContext value={level + 1}>   {/* provide */}
        {children}
      </LevelContext>
    </section>
  );
}

